package com.noora.assistant
import android.app.*;import android.content.*;import android.os.*;import android.speech.*;import java.util.*
class WakeWordService:Service(){private var r:SpeechRecognizer?=null;private val ch="noora_voice"
 override fun onCreate(){super.onCreate();getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel(ch,"NOORA Voice",NotificationManager.IMPORTANCE_LOW));startForeground(7,Notification.Builder(this,ch).setContentTitle("NOORA").setContentText("JARVIS wake-word service is active").setSmallIcon(android.R.drawable.ic_btn_speak_now).build());listen()}
 private fun listen(){if(!SpeechRecognizer.isRecognitionAvailable(this))return;r?.destroy();r=SpeechRecognizer.createSpeechRecognizer(this);r!!.setRecognitionListener(object:RecognitionListener{override fun onResults(x:Bundle){val s=x.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)?.joinToString(" ")?.lowercase(Locale.getDefault())? :"";if(Regex("\\bjarvis\\b").containsMatchIn(s))sendBroadcast(Intent(ACTION).putExtra("text",s));listen()};override fun onError(e:Int){listen()};override fun onReadyForSpeech(p:Bundle){};override fun onBeginningOfSpeech(){};override fun onRmsChanged(v:Float){};override fun onBufferReceived(b:ByteArray){};override fun onEndOfSpeech(){};override fun onPartialResults(p:Bundle){};override fun onEvent(t:Int,p:Bundle){}});val i=Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply{putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false)};r!!.startListening(i)}
 override fun onDestroy(){r?.destroy();super.onDestroy()};override fun onBind(i:Intent?):IBinder?=null
 companion object{const val ACTION="com.noora.assistant.JARVIS_HEARD"}}
